from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
# white components
white=(im.min(axis=2)>215)
seen=np.zeros_like(white)
for y in range(192):
 for x in range(256):
  if white[y,x] and not seen[y,x]:
   stack=[(x,y)]; seen[y,x]=1; p=[]
   while stack:
    xx,yy=stack.pop();p.append((xx,yy))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     nx,ny=xx+dx,yy+dy
     if 0<=nx<256 and 0<=ny<192 and white[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((nx,ny))
   if len(p)>10:
    a=np.array(p); print(len(p),a.min(0),a.max(0),a.mean(0))
# ASCII space stable, . dark table  :dark, etc full right to bottom; separate whitish and black
x0,x1,y0,y1=165,256,98,180
print('    '+''.join(str(x//10%10) for x in range(x0,x1)))
print('    '+''.join(str(x%10) for x in range(x0,x1)))
for y in range(y0,y1):
 chars=[]
 for r,g,b in im[y,x0:x1].astype(float):
  m=(r+g+b)/3
  c=' ' if m<15 else '.' if m<35 else ':' if m<70 else '=' if m<115 else '+' if m<155 else '*' if m<195 else '#' if m<225 else '@'
  chars.append(c)
 print(f'{y:03d} '+''.join(chars))
